 public sealed class FastCombatTests
 {
  const string Folder="Assets/IronRequiem/Prefabs/FastCombat",Lab="Assets/IronRequiem/Scenes/FastCombatExecutionLab.unity",Reports="Tools/IronRequiem/Reports/FastCombat";
  PlayerCharacterController player;StolenWeaponCarrier carrier;PlayerWeaponsManager manager;Keyboard keys;Mouse mouse;float capture;bool background;UnityEngine.InputSystem.Utilities.ReadOnlyArray<InputDevice>? devices;
  [UnitySetUp]public IEnumerator Setup(){capture=Time.captureDeltaTime;background=Application.runInBackground;Time.captureDeltaTime=1f/60;Time.timeScale=1;Application.runInBackground=true;devices=InputSystem.actions.devices;keys=InputSystem.AddDevice<Keyboard>();mouse=InputSystem.AddDevice<Mouse>();InputSystem.actions.devices=new InputDevice[]{keys,mouse};keys.MakeCurrent();mouse.MakeCurrent();EditorSceneManager.LoadSceneInPlayMode(Lab,new LoadSceneParameters(LoadSceneMode.Single));yield return null;yield return null;Object.FindAnyObjectByType<CombatLabMenu>().BeginGame();player=Object.FindAnyObjectByType<PlayerCharacterController>();carrier=player.GetComponent<StolenWeaponCarrier>();manager=player.GetComponent<PlayerWeaponsManager>();player.GetComponent<Health>().Invincible=true;player.enabled=false;Cursor.lockState=CursorLockMode.Locked;yield return null;}
  [UnityTearDown]public IEnumerator Cleanup(){Time.timeScale=1;Time.captureDeltaTime=capture;AudioListener.pause=false;var scene=SceneManager.GetActiveScene();SceneManager.SetActiveScene(SceneManager.CreateScene("FastCleanup"+Time.frameCount));yield return SceneManager.UnloadSceneAsync(scene);InputSystem.actions.devices=devices;InputSystem.RemoveDevice(keys);InputSystem.RemoveDevice(mouse);Cursor.lockState=CursorLockMode.None;Application.runInBackground=background;}
  void Move(Vector3 p){var cc=player.GetComponent<CharacterController>();cc.enabled=false;player.transform.position=p;cc.enabled=true;player.CharacterVelocity=Vector3.zero;Physics.SyncTransforms();}
  GameObject Spawn(string name){return Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(Folder+"/"+name+"_Fast.prefab"),new Vector3(0,0,-12),Quaternion.identity);}
  IEnumerator StopBot(GameObject go){yield return null;yield return null;go.GetComponent<EnemyController>().enabled=false;var mobile=go.GetComponent<EnemyMobile>();if(mobile)mobile.enabled=false;var big=go.GetComponent<BigBotCombat>();if(big)big.enabled=false;var agent=go.GetComponent<NavMeshAgent>();if(agent&&agent.enabled&&agent.isOnNavMesh)agent.isStopped=true;}
  void Aim(GameObject go,float gap=1.25f){var box=go.GetComponent<Collider>();Assert.That(box,Is.Not.Null);Move(new Vector3(box.bounds.center.x,.03f,box.bounds.min.z-gap));player.PlayerCamera.transform.LookAt(box.bounds.center);Physics.SyncTransforms();}
  IEnumerator Tap(Key key){InputSystem.QueueStateEvent(keys,new KeyboardState(key));yield return null;yield return null;InputSystem.QueueStateEvent(keys,new KeyboardState());yield return null;}
  [UnityTest]public IEnumerator ValuesAndMovement()
  {
   var original=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/IronRequiem/Prefabs/Player/Player_ModularArm_v07.prefab").GetComponent<PlayerCharacterController>();Assert.That(player.MaxSpeedOnGround,Is.EqualTo(original.MaxSpeedOnGround*1.15f).Within(.001));Assert.That(player.MaxSpeedInAir,Is.EqualTo(original.MaxSpeedInAir*1.15f).Within(.001));Assert.That(player.GetComponent<AdvancedPlayerMovement>().DashSpeed,Is.EqualTo(27.6f).Within(.001));Assert.That(player.GetComponent<AdvancedPlayerMovement>().DashDuration,Is.EqualTo(.18f));Assert.That(player.GetComponent<Health>().MaxHealth,Is.EqualTo(original.GetComponent<Health>().MaxHealth));
   foreach(var item in new[]{("T07_HitFeedback_v04","Assets/IronRequiem/Prefabs/Enemies/T07_HitFeedback_v04.prefab"),("BigBot_Burst_v10","Assets/IronRequiem/Prefabs/Enemies/BigBot_Burst_v10.prefab"),("HoverBot_CombatPolish","Assets/IronRequiem/Prefabs/Enemies/HoverBot_CombatPolish.prefab"),("Turret_CombatPolish","Assets/IronRequiem/Prefabs/Enemies/Turret_CombatPolish.prefab")})
   {var source=AssetDatabase.LoadAssetAtPath<GameObject>(item.Item2);var variant=AssetDatabase.LoadAssetAtPath<GameObject>(Folder+"/"+item.Item1+"_Fast.prefab");Assert.That(source&&variant,Is.True);Assert.That(variant.GetComponent<Health>().MaxHealth,Is.EqualTo(source.GetComponent<Health>().MaxHealth*.8f).Within(.001));var sourceAgent=source.GetComponent<NavMeshAgent>();var tunedAgent=variant.GetComponent<NavMeshAgent>();if(sourceAgent)Assert.That(tunedAgent.speed,Is.EqualTo(sourceAgent.speed*1.2f).Within(.001));var a=source.GetComponentsInChildren<NavigationModule>(true);var b=variant.GetComponentsInChildren<NavigationModule>(true);for(int i=0;i<a.Length;i++)Assert.That(b[i].MoveSpeed,Is.EqualTo(a[i].MoveSpeed*1.2f).Within(.001));var old=source.GetComponentsInChildren<WeaponController>(true);var current=variant.GetComponentsInChildren<WeaponController>(true);for(int i=0;i<old.Length;i++){Assert.That(current[i].DelayBetweenShots,Is.EqualTo(old[i].DelayBetweenShots));Assert.That(current[i].ProjectilePrefab.GetComponent<ProjectileStandard>().Damage,Is.EqualTo(old[i].ProjectilePrefab.GetComponent<ProjectileStandard>().Damage*.8f).Within(.001));}Assert.That(variant.GetComponentsInChildren<Component>(true).All(c=>c),Is.True);}
   player.enabled=true;Move(new Vector3(0,.03f,-29));player.PlayerCamera.transform.localRotation=Quaternion.identity;InputSystem.QueueStateEvent(keys,new KeyboardState(Key.W));yield return new WaitForSeconds(.65f);float speed=Vector3.ProjectOnPlane(player.CharacterVelocity,Vector3.up).magnitude;Assert.That(speed,Is.EqualTo(player.MaxSpeedOnGround).Within(.8f));InputSystem.QueueStateEvent(keys,new KeyboardState());System.IO.File.WriteAllText(Reports+"/movement.txt","Actual virtual W input ground speed="+speed+". All four enemy health/navigation/projectile variant values validated against source once. Unchanged shot intervals. Dash 27.6/.18; Soundtrack excluded at user request.");
  }
  [UnityTest]public IEnumerator T07ThresholdWallsRangeInventoryAndUniqueDelivery()
  {
   var go=Spawn("T07_HitFeedback_v04");yield return StopBot(go);var hp=go.GetComponent<Health>();var target=go.GetComponent<EnemyExecutionSource>();Aim(go);hp.TakeDamage(hp.MaxHealth*.25f,player.gameObject);yield return null;Assert.That(target.Eligible,Is.False);Assert.That(carrier.TryExecute(target),Is.False);var joint=go.GetComponentInChildren<DetachableCannon>(true);var jointHit=joint.GetComponentInChildren<Damageable>(true);Assert.That(jointHit.Health,Is.SameAs(hp));jointHit.InflictDamage(.1f,false,player.gameObject);yield return null;Assert.That(target.Eligible,Is.True);Assert.That(joint.IsDetached,Is.False);
   Aim(go,3.2f);yield return null;Assert.That(carrier.GetExecutionStatus(target),Is.EqualTo(CannonPickupStatus.TooFar));Assert.That(carrier.TryExecute(target),Is.False);Aim(go);var wall=GameObject.CreatePrimitive(PrimitiveType.Cube);wall.transform.position=(player.PlayerCamera.transform.position+go.GetComponent<Collider>().bounds.center)/2;wall.transform.localScale=new Vector3(6,5,.15f);Physics.SyncTransforms();yield return null;Assert.That(carrier.TryExecute(target),Is.False);Assert.That(carrier.ExecutionCandidate,Is.Null);Object.Destroy(wall);yield return null;Aim(go);
   var extra=new List<WeaponController>();var prototypes=new List<GameObject>();var baseWeapon=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/FPS/Prefabs/Weapons/Weapon_Blaster.prefab");for(int i=0;i<8;i++){var prototype=Object.Instantiate(baseWeapon);prototype.SetActive(false);prototypes.Add(prototype);if(manager.AddWeapon(prototype.GetComponent<WeaponController>()))extra.Add(manager.HasWeapon(prototype.GetComponent<WeaponController>()));}Assert.That(carrier.GetExecutionStatus(target),Is.EqualTo(CannonPickupStatus.InventoryFull));float before=hp.CurrentHealth;yield return Tap(Key.E);Assert.That(hp.CurrentHealth,Is.EqualTo(before));Assert.That(target.Delivered,Is.False);foreach(var w in extra)manager.RemoveWeapon(w);foreach(var p in prototypes)Object.Destroy(p);yield return null;
   Aim(go);yield return null;Assert.That(carrier.ExecutionStatus,Is.EqualTo(CannonPickupStatus.Ready));var hud=Object.FindAnyObjectByType<MechanicHud>();var prompt=(TMPro.TMP_Text)new SerializedObject(hud).FindProperty("prompt").objectReferenceValue;Assert.That(prompt.text,Does.Contain("[E] Ejecutar y tomar arma"));int deaths=0;hp.OnDie+=()=>deaths++;yield return Tap(Key.E);Assert.That(hp.CurrentHealth,Is.Zero);Assert.That(deaths,Is.EqualTo(1));Assert.That(target.Delivered,Is.True);Assert.That(carrier.Held,Is.Not.Null);Assert.That(carrier.Held.Ammo.Remaining,Is.EqualTo(carrier.Held.Ammo.Capacity));Assert.That(carrier.TryExecute(target),Is.False);yield return Tap(Key.E);Assert.That(deaths,Is.EqualTo(1));Assert.That(carrier.Held.EquippedWeapon.GetComponent<CannonChargeShot>(),Is.Not.Null);System.IO.File.WriteAllText(Reports+"/execution.txt","Actual T07 joint Damageable routes to root Health without detaching. Actual E: strict <75%, distance, solid wall, full inventory do not kill; free slot delivers T07 once and kills once; repeated press/direct attempt rejected; T07 keeps charge. Existing carrier/HUD/inventory used.");
  }
  [UnityTest]public IEnumerator NormalDeathsNoModulesAndBigBotLossStaysDecorative()
  {
   var t07=Spawn("T07_HitFeedback_v04");yield return StopBot(t07);t07.GetComponent<Health>().Kill();yield return new WaitForSeconds(.8f);Assert.That(Object.FindObjectsByType<StolenCannon>().Count(m=>m.State==StolenCannonState.Available||m.State==StolenCannonState.Thrown),Is.Zero);
   var big=Spawn("BigBot_Burst_v10");yield return StopBot(big);big.GetComponent<Health>().TakeDamage(big.GetComponent<Health>().MaxHealth*.8f,player.gameObject);yield return null;Assert.That(big.GetComponent<BigBotDestruction>().CannonDetached,Is.True);Assert.That(big.GetComponent<BigBotCombat>().ActiveCannonCount,Is.EqualTo(1));Assert.That(Object.FindObjectsByType<StolenCannon>().Count(m=>m.State==StolenCannonState.Available),Is.Zero);Assert.That(big.GetComponent<EnemyExecutionSource>().Eligible,Is.True);big.GetComponent<Health>().Kill();yield return new WaitForSeconds(1.9f);Assert.That(Object.FindObjectsByType<StolenCannon>().Count(m=>m.State==StolenCannonState.Available),Is.Zero);System.IO.File.WriteAllText(Reports+"/normal-death.txt","Normal T07 death, BigBot critical loss and death: no collectible modules. BigBot loss still switches to one-cannon emergency with decorative remnant. Death presentation preserved.");
  }
  [UnityTest]public IEnumerator BigBotExecuteBurstEnergyThrowAndOverdrive()
  {
   var big=Spawn("BigBot_Burst_v10");yield return StopBot(big);var hp=big.GetComponent<Health>();hp.TakeDamage(hp.MaxHealth*.3f,player.gameObject);Aim(big);yield return Tap(Key.E);var module=carrier.Held;Assert.That(module,Is.Not.Null);Assert.That(module.Ammo.Capacity,Is.EqualTo(120).Within(.001f));yield return new WaitForSeconds(1);var weapon=module.EquippedWeapon;var burst=weapon.GetComponent<CannonBurstShot>();Assert.That(burst,Is.Not.Null);Assert.That(burst.EnergyPerShot,Is.EqualTo(12));Assert.That(burst.ShotInterval,Is.EqualTo(.18f));Assert.That(burst.BurstPause,Is.EqualTo(1.5f));Assert.That(weapon.ProjectilePrefab.GetComponent<ProjectileStandard>().Damage,Is.EqualTo(30));Assert.That(module.Overdrive.CriticalThreshold,Is.EqualTo(.2f));player.PlayerCamera.transform.localRotation=Quaternion.identity;
   InputSystem.QueueStateEvent(mouse,new MouseState{buttons=1});yield return null;yield return null;InputSystem.QueueStateEvent(mouse,new MouseState());yield return new WaitForSeconds(.7f);Assert.That(burst.ShotsFired,Is.EqualTo(3));Assert.That(module.Ammo.Remaining,Is.EqualTo(84).Within(.001f));manager.SwitchWeapon(true);yield return new WaitForSeconds(.6f);Assert.That(module.Ammo.Remaining,Is.EqualTo(84).Within(.001f));manager.SwitchToWeaponIndex(Enumerable.Range(0,9).Single(i=>manager.GetWeaponAtSlotIndex(i)==weapon),true);yield return new WaitForSeconds(.8f);yield return Tap(Key.G);Assert.That(carrier.Held,Is.Null);Assert.That(module.State==StolenCannonState.Available||module.State==StolenCannonState.Thrown,Is.True);Assert.That(module.Ammo.Remaining,Is.EqualTo(84).Within(.001f));module.Ammo.Drain(60);Assert.That(module.Overdrive.IsArmed,Is.True);Assert.That(module.Ammo.Remaining,Is.EqualTo(24).Within(.001f));Assert.That(module.Overdrive.Smoke.isPlaying,Is.True);yield return new WaitForSeconds(5.3f);Assert.That(!module||module.Explosion.HasDetonated,Is.True);System.IO.File.WriteAllText(Reports+"/bigbot-weapon.txt","Actual E execution and M1 tap: 3 projectiles, damage prefab 30, energy 120 ->84; unchanged .18/1.5 burst. Switch preserves84; G throws;24 arms smoke/OVERDRIVE; detonates after grace. Critical ratio unchanged. No desktop input.");
  }
  // 2026-11-04: Big Bot execution is staged (leap on top, wrench cannon, shoot it with that cannon, jump back).
  [UnityTest]public IEnumerator BigBotExecutionLeapsRipsShootsAndLandsBack()
  {
   var big=Spawn("BigBot_Burst_v10");yield return StopBot(big);var hp=big.GetComponent<Health>();hp.TakeDamage(hp.MaxHealth*.3f,player.gameObject);Aim(big);player.enabled=true;yield return null;
   var startPos=player.transform.position;var sequence=player.GetComponent<BigBotExecutionSequence>();Assert.That(sequence,Is.Not.Null);int deaths=0;hp.OnDie+=()=>deaths++;
   yield return Tap(Key.E);Assert.That(carrier.Held,Is.Not.Null);Assert.That(sequence.IsRunning,Is.True);Assert.That(hp.CurrentHealth,Is.GreaterThan(0),"Kill waits for the shot");
   float maxY=startPos.y,t=0;var trace=new System.Text.StringBuilder();var motion=player.GetComponent<AdvancedPlayerMovement>();while(sequence.IsRunning&&t<5){t+=Time.deltaTime;maxY=Mathf.Max(maxY,player.transform.position.y);if(trace.Length<1500)trace.Append(" ["+t.ToString("F2")+" y="+player.transform.position.y.ToString("F2")+" s="+motion.IsScripted+" en="+player.enabled+"/"+motion.enabled+" g="+player.IsGrounded+" v="+player.CharacterVelocity.y.ToString("F1")+" dt="+Time.deltaTime.ToString("F3")+"]");yield return null;}
   Assert.That(sequence.IsRunning,Is.False);Assert.That(sequence.ShotCount,Is.EqualTo(1));Assert.That(deaths,Is.EqualTo(1));Assert.That(hp.CurrentHealth,Is.Zero);
   // executions-v02 (approved F1 §3.3): 1.50 s clock, perch beside the cannon shoulder (not on top), control back <= 2.0 s
   Assert.That(t,Is.InRange(1.3f,2.0f),"Sequence readable and <= 2.0 s");Assert.That(maxY-startPos.y,Is.GreaterThan(.5f),"Player leapt up to the cannon shoulder; perch="+sequence.Perch+" start="+startPos+" contact="+sequence.LastContact+" trace="+trace);
   Assert.That(Vector3.ProjectOnPlane(player.transform.position-startPos,Vector3.up).magnitude,Is.LessThan(.6f),"Player lands back where the leap started");
   Assert.That(carrier.Held.Ammo.Remaining,Is.EqualTo(carrier.Held.Ammo.Capacity).Within(.001f),"Presentation shot consumes no energy");
   Assert.That(player.GetComponent<AdvancedPlayerMovement>().IsScripted,Is.False);System.IO.File.WriteAllText(Reports+"/bigbot-execution-sequence.txt","duration="+t+" peak="+(maxY-startPos.y)+" landing offset="+Vector3.ProjectOnPlane(player.transform.position-startPos,Vector3.up).magnitude);
  }
  [UnityTest]public IEnumerator RuntimeProjectileAndDamageableUseReducedDamage()
  {
   var big=Spawn("BigBot_Burst_v10");yield return StopBot(big);var bot=big.GetComponent<BigBotCombat>();Assert.That(bot.Damage,Is.EqualTo(8));float observed=-1;bot.ProjectileSpawned+=p=>observed=p.GetComponent<ProjectileStandard>().Damage;var enemy=big.GetComponent<EnemyController>();enemy.enabled=true;yield return new WaitForSeconds(.3f);Assert.That(enemy.TryAtack(player.PlayerCamera.transform.position,bot.Cannons[0]),Is.True);Assert.That(observed,Is.EqualTo(8));enemy.enabled=false;var hp=player.GetComponent<Health>();hp.Invincible=false;float before=hp.CurrentHealth;var hurt=player.GetComponent<Damageable>();Assert.That(hurt,Is.Not.Null);hurt.InflictDamage(observed,false,big);Assert.That(before-hp.CurrentHealth,Is.EqualTo(8).Within(.001));hp.Invincible=true;System.IO.File.WriteAllText(Reports+"/damage.txt","Actual BigBot WeaponController projectile callback damage8 (source10). Existing player Damageable/Health subtracts8 once. Not a manual evasion/difficulty playthrough.");
  } }
